mod dense;mod linear;mod pencil;mod prepared;mod table_oracle;
#[path="../native-prepared-solvers/walk.rs"]mod walk;
use hec_native_ic::{counted,instance::pick_instance,rng::Rng};
fn main(){counted::disable();synthetic();let old=include_str!("../native-public-2lp/CONTROL.txt");let mut calls=0;let mut failures=0;
 for line in include_str!("INSTANCES.tsv").lines().skip(1){let v:Vec<_>=line.split('\t').collect();let g:usize=v[0].parse().unwrap();let p:u64=v[1].parse().unwrap();let cc:u64=v[2].parse().unwrap();let ell:u64=v[3].parse().unwrap();let inst=pick_instance(p,g).unwrap();assert_eq!(inst.c,cc);assert_eq!(inst.ell,ell);assert_eq!(inst.curve.f.c[..inst.curve.f.n].iter().map(u64::to_string).collect::<Vec<_>>().join(","),v[4]);let mut rng=Rng::new(2026111800^p^((g as u64)<<32));
 for case in 0..2{let sm=if case==0{1}else{17};let source=inst.curve.mul(&inst.d1,sm);let k=1+rng.below(ell-1);let target=inst.curve.mul(&source,k);let seed=2026111800+case as u64;let prefix=format!("CASE g={g} p={p} c={cc} ell={ell} source_multiple={sm} case={case} seed={seed} expected={k} ");assert!(old.lines().any(|l|l.starts_with(&prefix)));eprintln!("start g={g} p={p} sm={sm} case={case}");walk::validate(&inst.curve,&source,&target,ell);let prep=prepared::prepare(&inst.curve,true);let r=pencil::solve(&inst.curve,&source,&target,ell,512,true,&prep);if let Some(answer)=r.k{assert_eq!(answer,k);assert_eq!(inst.curve.mul(&source,answer),target);}else{failures+=1;}println!("CASE g={g} p={p} c={cc} ell={ell} sm={sm} case={case} expected={k} report={r:?}");calls+=1;
 }}assert_eq!(calls,22);eprintln!("SUMMARY initial_models=11 exact_public_workloads={calls} failures={failures} every_queried_norm_and_known_root_product_exact=true every_queried_split_brute_checked=true every_accepted_principal_group_identity_checked=true dense_lp_prefix=true no_automorphism_or_log_oracle=true no_speed_claim=true");if failures>0{std::process::exit(2);}}

fn synthetic(){use linear::{Linear,put};let mut l=Linear::new(3,24,1009);let mut rng=Rng::new(2026111903);for _ in 0..128{let mut row=std::collections::BTreeMap::new();for _ in 0..3{let j=4+rng.below(21)as usize;let v=1+rng.below(1008);put(&mut row,j,v,&l.f);}for j in 0..4{put(&mut row,j,1+rng.below(1008),&l.f);}let mut rhs=0;for(&j,&v)in &row{rhs=l.f.add(rhs,l.f.mul(v,(j as u64+7)%1009));}if let Some(k)=l.push(row,rhs,true){assert_eq!(k,10);}}assert_eq!(l.audits,128);assert!(l.max_lp_width>3);eprintln!("SYNTHETIC rows=128 dense_equal=true max_lp_width={} expanded_rows={}",l.max_lp_width,l.expanded_rows);}
